def retry(fn, attempts=3, exceptions=(OSError,)):
    """Call `fn()` up to `attempts` times; re-raise the last error."""
    if attempts < 1:
        raise ValueError("attempts must be >= 1")
    last = None
    for _ in range(attempts):
        try:
            return fn()
        except exceptions as exc:
            last = exc
    raise last

ops.new:
def retry(fn, attempts=3, exceptions=(OSError,), on_error=None):
    """Call `fn()` up to `attempts` times; re-raise the last error.

    `on_error(attempt, exc)` is called after each failed attempt (1-based).
    """
    if attempts < 1:
        raise ValueError("attempts must be >= 1")
    last = None
    for attempt in range(1, attempts):
        try:
            return fn()
        except exceptions as exc:
            last = exc
            if on_error is not None:
                on_error(attempt, exc)
    raise last

